code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and sum(1 for row in grid for x in row if x==grid[r][c])==2]
    # Boundary bars and isolated markers: project marker color inward from the nearest aligned bar.
    for r,c in marks:
        color=grid[r][c]
        # determine the aligned edge/bar, favor nearest edge along same row/column
        options=[]
        for rr in range(r):
            if grid[rr][c]!=bg: options.append((r-rr, 'up',rr))
        for rr in range(r+1,h):
            if grid[rr][c]!=bg: options.append((rr-r,'down',rr))
        for cc in range(c):
            if grid[r][cc]!=bg: options.append((c-cc,'left',cc))
        for cc in range(c+1,w):
            if grid[r][cc]!=bg: options.append((cc-c,'right',cc))
        if not options: continue
        _,direction,_=min(options)
        if direction=='up':
            for rr in range(0,r): out[rr][c]=color
        elif direction=='down':
            for rr in range(r+1,h): out[rr][c]=color
        elif direction=='left':
            for cc in range(0,c): out[r][cc]=color
        else:
            for cc in range(c+1,w): out[r][cc]=color
        out[r][c]=4
    return out
'''
